type ButtonProps = { children: ReactNode; href?: string; onClick?: () => void; secondary?: boolean; disabled?: boolean; type?: 'button' | 'submit' };
function Button({ children, href, onClick, secondary, disabled, type = 'button' }: ButtonProps) {
  const cls = `inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-5 text-sm font-bold transition duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2876b4] disabled:cursor-not-allowed disabled:opacity-50 ${secondary ? 'border border-[#d9e3eb] bg-white text-[#184b78] hover:bg-[#f3f8fb]' : 'bg-[#125a9c] text-white hover:bg-[#0d497f]'}`;
  if (href) return <Link href={href} className={cls}>{children}</Link>;
  return <button type={type} onClick={onClick} disabled={disabled} className={cls}>{children}</button>;
}
function Logo({ inverse = false }: { inverse?: boolean }) {
  return <Link href="/" aria-label="EDUCA — página inicial" className={`inline-flex items-center gap-2 font-extrabold tracking-[-.08em] text-[25px] ${inverse ? 'text-white' : 'text-[#14578e]'}`}>
    <span className="relative inline-flex h-8 w-8 items-center justify-center rounded-[10px] bg-[#135b98] text-[21px] italic leading-none text-white">e</span>
    <span>EDUCA<span className={`ml-1 inline-block h-1.5 w-1.5 rounded-full align-middle ${inverse ? 'bg-[#86d5a6]' : 'bg-[#33a36a]'}`} /></span>
  </Link>;
}
