function TeacherCard({ teacher }: { teacher: TeacherPublic }) {
  return <article className="flex flex-col rounded-2xl border border-[#e1e9ef] bg-white p-5 shadow-[0_3px_12px_rgba(18,54,84,.04)] transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-center gap-3"><Avatar name={teacher.name} src={teacher.photoUrl}/><div className="min-w-0"><h3 className="truncate font-bold text-[#1d3b55]">{teacher.name}</h3><p className="text-xs text-[#73869a]">{teacher.subjects.join(' · ')}</p></div></div><p className="mt-4 line-clamp-3 min-h-[66px] text-sm leading-6 text-[#566d80]">{teacher.bio}</p><div className="mt-3 flex flex-wrap gap-2">{teacher.levels.slice(0,3).map(level=><span key={level} className="rounded-full bg-[#f0f5f8] px-2.5 py-1 text-xs text-[#47647c]">{level}</span>)}</div><div className="mt-auto flex items-center justify-between border-t border-[#edf1f4] pt-4"><div className="text-sm font-bold text-[#2d4d67]">{teacher.hourlyRateMzn != null ? `${teacher.hourlyRateMzn.toLocaleString('pt-PT')} MZN/h` : 'Valor a combinar'}<p className="mt-1 flex items-center gap-1 text-xs font-medium text-[#73869a]">{teacher.rating != null && <><Star size={12} className="fill-[#da9c32] text-[#da9c32]"/>{teacher.rating.toFixed(1)} · </>}{teacher.reviewCount} avaliações</p></div><Button href={`/professores/${teacher.id}`} secondary>Ver perfil <ArrowRight size={15}/></Button></div></article>;
}
